        //                 "instrument_name": "ETH-PERPETUAL",
        //                 "is_liquidation": false,
        //                 "is_rebalance": false,
        //                 "label": "",
        //                 "last_update_timestamp": 1590486335742,
        //                 "max_show": 21,
        //                 "order_id": "ETH-584864807",
        //                 "order_state": "filled",
        //                 "order_type": "limit",
        //                 "post_only": false,
        //                 "price": 198.75,
        //                 "reduce_only": true,
        //                 "replaced": false,
        //                 "time_in_force": "good_til_cancelled",
        //                 "web": false
        //             },
        //             "trades": [
        //                 {
        //                     "amount": 21,
        //                     "direction": "sell",
        //                     "fee": 0.00007766,
        //                     "fee_currency": "ETH",
        //                     "index_price": 202.86,
        //                     "instrument_name": "ETH-PERPETUAL",
        //                     "liquidity": "T",
        //                     "mark_price": 202.79,
        //                     "matching_id": null,
        //                     "order_id": "ETH-584864807",
        //                     "order_type": "limit",
        //                     "post_only": false,
        //                     "price": 202.8,
        //                     "reduce_only": true,
        //                     "state": "filled",
        //                     "tick_direction": 0,
        //                     "timestamp": 1590486335742,
        //                     "trade_id": "ETH-2696097",
        //                     "trade_seq": 1966068
        //                 }
        //             ]
        //         }
        //     }
        //
        $result = $this->safe_dict($response, 'result', array());
        $order = $this->safe_dict($result, 'order', array());
        $trades = $this->safe_list($result, 'trades', array());
        $order['trades'] = $trades;
        return $this->parse_order($order, $market);
    }

